package com.godjiismp.client.ui;
import com.godjiismp.skills.*;import com.godjiismp.weapons.LegendaryItems;import net.fabricmc.api.ClientModInitializer;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper;import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;import net.minecraft.client.KeyMapping;import net.minecraft.client.renderer.item.ItemProperties;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import com.mojang.blaze3d.platform.InputConstants;import org.lwjgl.glfw.GLFW;
public final class SkillsClient implements ClientModInitializer {private static KeyMapping key;@Override public void onInitializeClient(){key=KeyBindingHelper.registerKeyBinding(new KeyMapping("key.godjiismp_newdays.skills",InputConstants.Type.KEYSYM,GLFW.GLFW_KEY_K,"key.categories.misc"));ClientPlayNetworking.registerGlobalReceiver(SkillPayload.TYPE,(payload,ctx)->ctx.client().execute(()->SkillsScreen.receive(payload)));ClientPlayNetworking.registerGlobalReceiver(SkillOpenPayload.TYPE,(payload,ctx)->ctx.client().execute(SkillsScreen::open));ItemProperties.register(LegendaryItems.get(4),ResourceLocation.withDefaultNamespace("pull"),(stack,level,entity,seed)->entity!=null&&entity.getUseItem()==stack?(stack.getUseDuration(entity)-entity.getUseItemRemainingTicks())/20.0f:0.0f);ItemProperties.register(LegendaryItems.get(4),ResourceLocation.withDefaultNamespace("pulling"),(stack,level,entity,seed)->entity!=null&&entity.isUsingItem()&&entity.getUseItem()==stack?1.0f:0.0f);ClientTickEvents.END_CLIENT_TICK.register(client->{if(key.consumeClick()&&client.player!=null)ClientPlayNetworking.send(new SkillRequestPayload());});}}
